Game fixture(){Game g;std::string error;if(!g.importScenario(std::filesystem::path(H3_TEST_SOURCE_ROOT)/"assets/demo/scenarios/dead-and-buried-1.json",error,8,131,4))throw std::runtime_error(error);std::erase_if(g.objects,[](auto&o){return o.type==ObjectType::Monster;});return g;}
int add(Game&g,int cls,int offset=0){Object o;o.id=90000+cls+offset;o.pos=g.hero.pos;o.level=g.mapLevel;o.type=ObjectType::Site;o.sourceClass=cls;o.name=adventureSiteName(cls);g.objects.push_back(o);return o.id;}
