 g=fixture();int fountain=add(g,30);g.visit(fountain);int fortune=g.adventureModifier(g.hero,1);auto rng=g.randomState;g.hero.adventureBonuses.clear();g.visit(fountain);check(g.adventureModifier(g.hero,1)==fortune&&g.randomState==rng,"Fountain rerolled after battle within the same week");
