 g=fixture();int spring=add(g,48);g.hero.mana=1;g.visit(spring);check(g.hero.mana==2*g.maxMana()&&g.validate(),"Magic spring failed overcharge or validation");g.hero.mana=0;g.visit(spring);check(g.hero.mana==0,"Magic spring refilled twice in a week");auto right=g.hero.pos;g.hero.pos.x--;check(g.objectAt(g.hero.pos)&&g.objectAt(g.hero.pos)->id==spring,"Magic spring left entrance is not selectable");g.visit(spring);check(g.hero.mana==2*g.maxMana(),"Magic spring entrances do not have independent weekly charges");g.hero.mana=0;g.visit(spring);check(g.hero.mana==0,"Left magic spring entrance paid twice");g.hero.pos=right;g.day=8;g.visit(spring);int charged=g.hero.mana;g.computerQueue.clear();for(auto&[id,h]:g.heroes)if(h.owner>0)h.value.movement=0;g.endDay();check(g.hero.mana==charged,"New day removed overcharged mana");check(g.save(path,error),error);check(loaded.load(path,error)&&loaded.hero.mana==charged,"Overcharged mana failed save/load");std::filesystem::remove(path);
